shikaku/bounds.py:
"""Area-based upper bounds."""

def additional_bound(areas: list[int], used: frozenset[int], remaining: int) -> int:
    """Maximum number of cheapest unused representable areas fitting the budget."""
    count = 0
    for area in areas:
        if area in used:
            continue
        if area > remaining:
            break
        remaining -= area
        count += 1
    return count

shikaku/config.py:
"""Explicit, validated solver settings shared by CLI and experiments."""

import json
from pathlib import Path


def load_config(path: Path | None = None) -> dict:
    config = ({"solver": "skyline", "options": {"prune": True}}
              if path is None else json.loads(path.read_text(encoding="utf-8")))
    if (not isinstance(config, dict) or set(config) != {"solver", "options"}
            or config["solver"] != "skyline"
            or not isinstance(config["options"], dict)
            or set(config["options"]) != {"prune"}
            or type(config["options"]["prune"]) is not bool):
        raise ValueError('expected solver="skyline" and options={"prune": boolean}')
    return config

shikaku/model.py:
"""Shared rectangle and serialized solver result types."""

from dataclasses import dataclass

@dataclass(frozen=True)
class Rect:
    row: int
    col: int
    height: int
    width: int

    @property
    def area(self) -> int:
        return self.height * self.width

shikaku/validation.py:
"""Independent witness validation."""

from .model import Rect


def validate_partition(n: int, rects: list[Rect]) -> int:
    """Independent cell-based witness check; returns the distinct-area count."""
    if n < 1:
        raise ValueError("n must be positive")
    occupied: set[tuple[int, int]] = set()
    for r in rects:
        if (r.row < 0 or r.col < 0 or r.height < 1 or r.width < 1
                or r.row + r.height > n or r.col + r.width > n):
            raise ValueError("rectangle outside grid or non-positive dimensions")
        for row in range(r.row, r.row + r.height):
            for col in range(r.col, r.col + r.width):
                cell = row, col
                if cell in occupied:
                    raise ValueError("overlapping rectangles")
                occupied.add(cell)
    if len(occupied) != n * n:
        raise ValueError("partition has uncovered cells")
    return len({r.area for r in rects})

tests/oracle.py:
"""Independent cell-mask exhaustive oracle for small grids."""

def cell_oracle(n: int) -> tuple[int, int]:
    """Enumerate all partitions: no skyline, area bound, seed, or memoization.

    Branch on the LAST free cell, and try all rectangles containing that cell.
    """
    candidates = [[] for _ in range(n * n)]
    for top in range(n):
        for bottom in range(top + 1, n + 1):
            for left in range(n):
                for right in range(left + 1, n + 1):
                    cells = [r * n + c for r in range(top, bottom)
                             for c in range(left, right)]
                    mask = sum(1 << c for c in cells)
                    for c in cells:
                        candidates[c].append((mask, len(cells)))
    full = (1 << (n * n)) - 1
    best = leaves = 0

    def visit(occupied: int, used: frozenset[int]) -> None:
        nonlocal best, leaves
        if occupied == full:
            best = max(best, len(used))
            leaves += 1
            return
        cell = (full ^ occupied).bit_length() - 1
        for mask, area in candidates[cell]:
            if not mask & occupied:
                visit(occupied | mask, used | {area})

    visit(0, frozenset())
    return best, leaves

tests/test_correctness.py:
"""Cross-check skyline search against independent full enumeration."""

import unittest
from shikaku import Rect, solve, validate_partition
from shikaku.constructions import initial_partition
from tests.oracle import cell_oracle


class BaselineTests(unittest.TestCase):
    def test_cross_check_all_partitions(self):
        for n in range(1, 5):
            with self.subTest(n=n):
                expected, leaves = cell_oracle(n)
                for prune in (False, True):
                    result = solve(n, prune=prune)
                    self.assertEqual(result["status"], "OPTIMAL")
                    self.assertEqual(result["k"], expected)
                    self.assertEqual(validate_partition(n, [Rect(**r) for r in
                                                           result["rectangles"]]), expected)
                    if not prune:
                        self.assertEqual(result["complete_partitions"], leaves)

    def test_note_exact_values(self):
        for n, expected in [(7, 9), (8, 10), (13, 17)]:
            result = solve(n)
            self.assertEqual(result["k"], expected)

    def test_construction(self):
        for n in range(1, 41):
            score = validate_partition(n, initial_partition(n))
            self.assertGreaterEqual(score, n + 2 * (((n + 1) // 2 - 1) // 3))

    def test_timeout_is_not_infeasibility(self):
        result = solve(5, time_limit=0)
        self.assertEqual(result["status"], "TIME_LIMIT")
        self.assertIsNone(result["k"])
        self.assertLess(result["lower_bound"], result["upper_bound"])
        validate_partition(5, [Rect(**r) for r in result["rectangles"]])

    def test_invalid_input(self):
        for n in (0, -1, 1.5, True):
            with self.assertRaises(ValueError):
                solve(n)
        for limit in (-1, float("nan"), float("inf")):
            with self.assertRaises(ValueError):
                solve(2, time_limit=limit)


if __name__ == "__main__":
    unittest.main()

